import{_ as t,o as a,c as o,ah as n}from"./chunks/framework.DDXs_i7t.js";const c=JSON.parse(`{"title":"Screenplay Update: Scene 31 - The Art of Favouritism","description":"Heidi Horten (Birgit Minichmayr) explains the 'Aesthetics of the Whole' and why donations are just points in a picture.","frontmatter":{"title":"Screenplay Update: Scene 31 - The Art of Favouritism","description":"Heidi Horten (Birgit Minichmayr) explains the 'Aesthetics of the Whole' and why donations are just points in a picture.","date":"2026-02-27T00:00:00.000Z"},"headers":[],"relativePath":"en/logbuch/szene-mazenatentum.md","filePath":"en/logbuch/szene-mazenatentum.md"}`),i={name:"en/logbuch/szene-mazenatentum.md"};function s(r,e,l,h,p,d){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="screenplay-update-scene-31-the-art-of-favouritism" tabindex="-1">Screenplay Update: Scene 31 - The Art of Favouritism <a class="header-anchor" href="#screenplay-update-scene-31-the-art-of-favouritism" aria-label="Permalink to &quot;Screenplay Update: Scene 31 - The Art of Favouritism&quot;">​</a></h1><p><strong>STYLE:</strong> High-gloss aesthetic. A bright, modern private museum (similar to the Heidi Horten Collection in Vienna). The camera glides over incredibly expensive paintings by Warhol and Picasso.</p><p><strong>CAST:</strong></p><ul><li><strong>Heidi Horten:</strong> Birgit Minichmayr (in an extravagant designer suit, hung with pearls)</li><li><strong>The Young Reporter:</strong> A slightly intimidated man in a poorly fitting suit.</li></ul><hr><p><strong>INT. PRIVATE MUSEUM - DAY</strong></p><p>Heidi (Minichmayr) stands in front of a huge, colorful painting. She holds a glass of champagne in which the carbonation bubbles almost rhythmically.</p><p><strong>HEIDI</strong> (with a deep, smoky voice and a slight Viennese accent) Look at that, darling. A Picasso. Do you know what&#39;s special about a Picasso? It&#39;s not just paint on canvas. It&#39;s a statement. It says: &quot;I can afford the reality I want.&quot;</p><p><strong>REPORTER</strong> (takes notes) Impressive, Mrs. Horten. But many wonder... where does the passion for art come from? And are there parallels to your... well... political engagement?</p><p><strong>HEIDI</strong> (laughs quietly, a throaty laugh) Oh, come on! Politics, art... it&#39;s all the same, my dear. It&#39;s about <em>patronage</em>. An artist needs a frame for their work to be effective. And a party? It just needs a frame too, so it can... work properly.</p><p>She takes a step closer to a portrait of her late husband Helmut.</p><p><strong>HEIDI</strong> Helmut always said: &quot;Heidi, a department store is like a museum. You have to show people what they should desire.&quot; I&#39;m doing nothing different now. I&#39;m showing the world what a beautiful Austria looks like. And if that requires a few donations here and there...</p><p><strong>REPORTER</strong> Critics call it influencing. Or donation splitting to bypass the Court of Audit.</p><p><strong>HEIDI</strong> (looks at him directly, her eyes flashing coolly) Splitting? What an ugly word. I call it <em>pointillism</em>. Like with Seurat! Many small dots only result in the large, glamorous picture from a distance. Those who only see the individual dots have no sense of the aesthetics of the whole.</p><p>She takes a sip of champagne.</p><p><strong>HEIDI</strong> You know, darling... art on buildings is good. But art on the <em>state</em>? That is the true supreme discipline.</p><p><strong>FADE TO BLACK.</strong></p>',17)])])}const g=t(i,[["render",s]]);export{c as __pageData,g as default};
